package isao.photorate.imageRecognition

import isao.photorate.imageRecognition.search.ClipTokenizer
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Unit tests for [isao.photorate.imageRecognition.search.ClipTokenizer] against a self-contained
 * tokenizer.json fixture. The fixture is generated by
 * `ml/original_models/onnx/generate_tokenizer_fixture.py` from the real MobileCLIP tokenizer and
 * VERIFIED to produce identical token IDs to HuggingFace's `tokenizers` library for the sample
 * descriptions.
 *
 * If the model/tokenizer is replaced, re-run that script and copy the new JSON (and expected IDs)
 * here.
 */
class ClipTokenizerTest {

  // Generated by ml/original_models/onnx/generate_tokenizer_fixture.py (default texts). It
  // contains only the vocab entries + merges needed for the sample
  // descriptions, plus the special tokens. Re-run the script to regenerate.
  private val fixtureJson =
    """
    {"version":"1.0","truncation":null,"padding":null,"added_tokens":[{"id":49406,"content":"<|startoftext|>","single_word":false,"lstrip":false,"rstrip":false,"normalized":true,"special":true},{"id":49407,"content":"<|endoftext|>","single_word":false,"lstrip":false,"rstrip":false,"normalized":false,"special":true}],"normalizer":{"type":"Sequence","normalizers":[{"type":"NFC"},{"type":"Replace","pattern":{"Regex":"\\s+"},"content":" "},{"type":"Lowercase"}]},"pre_tokenizer":{"type":"Sequence","pretokenizers":[{"type":"Split","pattern":{"Regex":"'s|'t|'re|'ve|'m|'ll|'d|[\\p{L}]+|[\\p{N}]|[^\\s\\p{L}\\p{N}]+"},"behavior":"Removed","invert":true},{"type":"ByteLevel","add_prefix_space":false,"trim_offsets":true,"use_regex":true}]},"post_processor":{"type":"RobertaProcessing","sep":["<|endoftext|>",49407],"cls":["<|startoftext|>",49406],"trim_offsets":false,"add_prefix_space":false},"decoder":{"type":"ByteLevel","add_prefix_space":true,"trim_offsets":true,"use_regex":true},"model":{"type":"BPE","dropout":null,"unk_token":"<|endoftext|>","continuing_subword_prefix":"","end_of_word_suffix":"</w>","fuse_unk":false,"byte_fallback":false,"vocab":{"t":83,"u":84,"r":81,"l":75,"e":68,"turtle</w>":10912,"c":66,"a":64,"cat</w>":2368,"a</w>":320,"n":77,"can</w>":753,"o":78,"f":69,"of</w>":539,"tuna</w>":15037,"j":73,"jar</w>":10837,"d":67,"and</w>":537,"h":71,"hand</w>":2463,"y":88,"i":72,"g":70,"lying</w>":7175,"w":86,"with</w>":593,"m":76,"s":82,"lemons</w>":29576,"in":512,"an":514,"g</w>":326,"ing</w>":519,"on":521,"it":529,"le":534,"t</w>":339,"at</w>":536,"d</w>":323,"f</w>":325,"n</w>":333,"an</w>":550,"ur":565,"un":569,"e</w>":324,"le</w>":579,"wit":584,"h</w>":327,"r</w>":337,"ar</w>":625,"s</w>":338,"ons</w>":708,"ying</w>":910,"tur":985,"tun":1415,"tle</w>":5825,"lem":10213},"merges":["i n","a n","in g</w>","o n","i t","l e","a t</w>","an d</w>","o f</w>","a n</w>","u r","u n","l e</w>","w it","wit h</w>","a r</w>","on s</w>","c an</w>","y ing</w>","t ur","t un","c at</w>","h and</w>","t le</w>","l ying</w>","le m","j ar</w>","tur tle</w>","tun a</w>","lem ons</w>"]}}
    """
      .trimIndent()

  private val tokenizer = ClipTokenizer(fixtureJson)

  @Test
  fun `encodes Turtle with start, word, and end tokens`() {
    val ids = tokenizer.encode("Turtle")
    assertEquals(49406, ids[0], "missing <|startoftext|>")
    assertEquals(
      10912,
      ids[1],
      "turtle</w> id differs from HF tokenizers ground truth",
    )
    assertEquals(49407, ids[2], "missing <|endoftext|>")
  }

  @Test
  fun `matches HuggingFace tokenizers ids for all sample descriptions`() {
    // Ground truth captured from the `tokenizers` Python
    // library on the
    // REAL tokenizer.json (see
    // ml/original_models/onnx/generate_tokenizer_fixture.py output).
    val cases =
      mapOf(
        "Turtle" to
          intArrayOf(
            49406,
            10912,
            49407,
          ),
        "Cat" to
          intArrayOf(
            49406,
            2368,
            49407,
          ),
        "a can of tuna" to
          intArrayOf(
            49406,
            320,
            753,
            539,
            15037,
            49407,
          ),
        "a jar and a hand" to
          intArrayOf(
            49406,
            320,
            10837,
            537,
            320,
            2463,
            49407,
          ),
        "cat lying with lemons" to
          intArrayOf(
            49406,
            2368,
            7175,
            593,
            29576,
            49407,
          ),
      )
    for ((text, expected) in cases) {
      val ids = tokenizer.encode(text)
      assertContentEquals(
        expected,
        ids.copyOf(expected.size),
        "token ids for '$text' differ from HF tokenizers",
      )
    }
  }

  @Test
  fun `pads to 77 tokens with pad id zero`() {
    val ids = tokenizer.encode("Turtle")
    assertEquals(
      77,
      ids.size,
      "context length must be 77",
    )
    // "Turtle" is exactly 3 tokens; pad id 0 starts right
    // after the EOS.
    assertEquals(
      49407,
      ids[2],
      "EOS token must be at index 2",
    )
    assertTrue(
      ids.drop(3).all { it == 0 },
      "padding must be pad id 0 from index 3 on",
    )
  }

  @Test
  fun `truncates to context length keeping start and end tokens`() {
    // "cat lying with lemons" -> 6 tokens; force a tiny
    // context.
    val ids =
      tokenizer.encode(
        "cat lying with lemons",
        contextLength = 4,
      )
    assertEquals(4, ids.size)
    assertEquals(
      49406,
      ids[0],
      "start token must be kept",
    )
    assertEquals(49407, ids[3], "end token must be kept")
  }

  @Test
  fun `normalizes case and whitespace like the HF normalizer`() {
    assertContentEquals(
      tokenizer.encode("Turtle"),
      tokenizer.encode("turtle"),
      "should be case-insensitive",
    )
    assertContentEquals(
      tokenizer.encode("a can of tuna"),
      tokenizer.encode("  a   can   of  tuna  "),
      "should trim and collapse whitespace",
    )
  }
}
